from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class IprtParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        gateway = self.enb_ent_config.get('gateway_ip')
        if not gateway:
            gateway = kwargs['env_config']['EMSSIM_IP']

        static_route_params = {
            'destIpAddr': '0.0.0.0',
            'destinationIpPrefixLength': 0,
            'gateway': gateway,
            # 'preSrcIpv4Addr': '0.0.0.0',
            # 'preference': 1
        }

        for subparam_name, subparam_value in static_route_params.items():
            self.set_struct_parameter('staticRoutes', subparam_name, subparam_value)
